{"command": "cd /workspace && cat > work/fx2.py <<'EOF'
import numpy as np, base64, json, sys
SRD=8363
def b64(x): return base64.b64encode(np.clip(x*26000,-32768,32767).astype('<i2').tobytes()).decode()
L=32
sust=np.sin(2*np.pi*np.arange(L)/L)
sust=np.tile(sust, 120)
calls=[{"name":"module_new","arguments":{"channels":2,"name":"FX2"}},
 {"name":"song_set","arguments":{"bpm":120,"speed":6}},
 {"name":"pattern_set_length","arguments":{"pattern":0,"rows":64}},
 {"name":"sample_create_from_pcm","arguments":{"instrument":1,"sample":0,"pcm":b64(sust),"encoding":"int16","name":"LOOP"}},
 {"name":"sample_set","arguments":{"instrument":1,"sample":0,"relative_note":0,"loop_start":0,"loop_length":len(sust),"flags":1,"volume":64,"panning":128}},
]
def cell(row,**kw):
    a={"pattern":0,"row":row,"channel":0}; a.update(kw); return {"name":"pattern_set_cell","arguments":a}
which=sys.argv[1]
if which=="base":
    calls+=[cell(0,note=49,instrument=1)]
elif which=="vslide":
    calls+=[cell(0,note=49,instrument=1,effect=10,effect_param=0x08)]
elif which=="porta":
    calls+=[cell(0,note=49,instrument=1),cell(8,effect=3,effect_param=0x20),cell(8,note=61),cell(20,effect=3,effect_param=0x40)]
elif which=="vib":
    calls+=[cell(0,note=49,instrument=1,effect=4,effect_param=0x24)]
elif which=="arp":
    calls+=[cell(0,note=49,instrument=1,effect=0,effect_param=0x37)]
elif which=="finevib":
    calls+=[cell(0,note=49,instrument=1,effect=4,effect_param=0x11)]
calls.append({"name":"module_render","arguments":{"path":"work/fx_%s.wav"%which,"rate":44100,"bits":16}})
json.dump(calls,open('work/bfx2_%s.json'%which,'w'))
EOF
for w in base vslide porta vib arp; do python3 work/fx2.py $w; ft2 batch work/bfx2_$w.json > /dev/null; done; ls -la work/*.wav"}

